INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2136659', 'Rwandan monarchy referendum, 1961', 'A referendum on the monarchy was held in Rwanda on 25 September 1961, concurrent with parliamentary elections. The referendum asked two questions: whether the monarchy should be retained after independence the following year, and whether the incumbent, Kigeli V, should remain King.', 1961, 9, 25, NULL, NULL, NULL, 'day', '25 September 1961', 37, 'https://en.wikipedia.org/wiki/1961_Rwandan_monarchy_referendum'),
  ('Q107548731', 'Bugesera invasion', 'The Bugesera invasion (French: Invasion de Bugesera), also known as the Bloody Christmas (French: Noël Rouge), was a military attack which was conducted against Rwanda by rebels called Inyenzi who aimed to overthrow the government in December 1963. The Inyenzi were a collection of ethnically Tutsi exiles who were affiliated with the Rwandan political party Union Nationale Rwandaise (UNAR), which had supported Rwanda''s deposed Tutsi monarchy.', 1963, 12, 21, 1963, 12, 27, 'day', '21 December 1963 – 27 December 1963', 26, 'https://en.wikipedia.org/wiki/Bugesera_invasion'),
  ('Q4575699', '1973 Rwandan coup d''état', 'The 1973 Rwandan coup d''état, also known as the Coup d''état of 5 July (French: Coup d''état du 5 Juillet), was a military coup staged by Juvénal Habyarimana against incumbent president Grégoire Kayibanda in the Republic of Rwanda. The coup took place on 5 July 1973 and was considered by many as a betrayal.', 1973, 7, 5, NULL, NULL, NULL, 'day', '5 July 1973', 43, 'https://en.wikipedia.org/wiki/1973_Rwandan_coup_d''%C3%A9tat'),
  ('Q426722', 'Rwandan Civil War', 'The Rwandan Civil War was a large-scale civil war in Rwanda which was fought between the Rwandan Armed Forces, representing the incumbent Third Rwandese Republic, and the rebel Rwandan Patriotic Front (RPF) from 1 October 1990 to 18 July 1994. The war arose from the long-running dispute between the Hutu and Tutsi groups within the Rwandan population.', 1990, 10, 1, 1993, 8, 4, 'day', '1 October 1990 – 4 August 1993', 68, 'https://en.wikipedia.org/wiki/Rwandan_Civil_War'),
  ('Q131297', '1994 Genocide against Tutsi', 'The Rwandan genocide, also known as the genocide against Tutsi, occurred from 7 April to 19 July 1994 during the Rwandan Civil War. Over a span of approximately 100 days, members of the Tutsi ethnic group, as well as some moderate Hutu and Twa, were systematically killed by Hutu militias.', 1994, NULL, NULL, 1994, 7, 4, 'year', '1994', 85, 'https://en.wikipedia.org/wiki/Rwandan_genocide'),
  ('Q655304', 'Nyarubuye massacre', 'The Nyarubuye massacre was the killing of an estimated 20,000 civilians on April 15, 1994 at the Nyarubuye Roman Catholic Church in Kibungo Province, 140 km (87 mi) east of the Rwandan capital Kigali. The victims were Tutsis.', 1994, 4, 15, 1994, 4, 16, 'day', '15 April 1994 – 16 April 1994', 37, 'https://en.wikipedia.org/wiki/Nyarubuye_massacre'),
  ('Q838695', 'First Congo War', 'The First Congo War, also known as Africa''s First World War, was a civil and international military conflict that lasted from 24 October 1996 to 16 May 1997, primarily taking place in Zaire (which was renamed the Democratic Republic of the Congo during the conflict). The war resulted in the overthrow of Zairean President Mobutu Sese Seko, who was replaced by rebel leader Laurent-Désiré Kabila.', 1996, 10, 24, 1997, 5, 16, 'day', '24 October 1996 – 16 May 1997', 72, 'https://en.wikipedia.org/wiki/First_Congo_War'),
  ('Q75756', 'Second Congo War', 'The Second Congo War, also known as Africa''s World War or the Great War of Africa, was a major conflict that began on 2 August 1998 in the Democratic Republic of the Congo (DRC), just over a year after the First Congo War. The war initially erupted when Congolese president Laurent-Désiré Kabila turned against his former allies from Rwanda and Uganda, who had helped him seize power.', 1998, 8, 2, 2003, 6, 30, 'day', '2 August 1998 – 30 June 2003', 75, 'https://en.wikipedia.org/wiki/Second_Congo_War'),
  ('Q1021172', 'Republic of the Congo civil war', 'The Second Republic of the Congo Civil War, also known as the Second Brazzaville-Congolese Civil War, was the second of two ethnopolitical civil conflicts in the Republic of the Congo which lasted from 5 June 1997 to 29 December 1999. The war served as the continuation of the civil war of 1993–1994 and involved militias representing three political candidates.', 1999, 12, 29, 1999, NULL, NULL, 'day', '1999', 52, 'https://en.wikipedia.org/wiki/Republic_of_the_Congo_Civil_War_(1997%E2%80%931999)'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q112535922', 'Democratic Republic of the Congo–Rwanda conflict', 'A conflict began between the Democratic Republic of the Congo (DRC) and Rwanda in 2022 after Rwandan forces intervened in the DRC to provide military support to the March 23 Movement (M23) rebel group, including fighting alongside them against the Congolese military (FARDC) and pro-government militias. A peace agreement between Rwanda and the DRC was signed on 27 June 2025, though fighting has continued and Rwandan troops remain in the DRC. Since the Second Congo War the eastern provinces of the DRC have been the site of an ongoing insurgency by various rebel groups, most notably the March…', 2022, 3, 27, NULL, NULL, NULL, 'day', '27 March 2022', 51, 'https://en.wikipedia.org/wiki/Democratic_Republic_of_the_Congo%E2%80%93Rwanda_conflict_(2022%E2%80%93present)'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods'),
  ('Q132369865', '2025 Bukavu offensive', 'The 2025 Bukavu offensive was a military operation conducted by M23 rebels in the eastern Democratic Republic of the Congo (DRC), centered around their advance toward Bukavu, the provincial capital of South Kivu. This military campaign began in February 2025, following the group''s successful capture of Goma in the neighboring North Kivu province, and concluded with the M23 rebels’ successful capture of Bukavu just over a week later.', 2025, 2, 5, NULL, NULL, NULL, 'day', '5 February 2025', 41, 'https://en.wikipedia.org/wiki/2025_Bukavu_offensive'),
  ('Q135274035', '2025 Democratic Republic of the Congo–Rwanda peace agreement', 'The Democratic Republic of the Congo–Rwanda peace agreement, officially the Washington Accords for Peace and Prosperity, is a peace treaty intended to end the conflict between the Democratic Republic of the Congo (DRC) and Rwanda, signed on June 27, 2025, in Washington, D.C., United States. The main points of the agreement call for the withdrawal of Rwandan troops from the eastern DRC and for the Congolese government to end its support for the Democratic Forces for the Liberation of Rwanda (FDLR) militia.', 2025, 6, 27, NULL, NULL, NULL, 'day', '27 June 2025', 37, 'https://en.wikipedia.org/wiki/2025_DRC%E2%80%93Rwanda_peace_agreement');
